-- Brings local dev DB (zgames) up to match the server's cgagames schema (source of truth).
-- Generated by diffing `mysqldump --no-data` output from both databases on 2026-09-22.

CREATE TABLE IF NOT EXISTS `gift_card_codes` (
  `id` varchar(36) NOT NULL,
  `createdAt` datetime(6) NOT NULL DEFAULT current_timestamp(6),
  `updatedAt` datetime(6) NOT NULL DEFAULT current_timestamp(6) ON UPDATE current_timestamp(6),
  `deletedAt` datetime(6) DEFAULT NULL,
  `variantId` varchar(36) DEFAULT NULL,
  `code` text NOT NULL,
  `status` enum('available','sold','disabled') NOT NULL DEFAULT 'available',
  `source` enum('manual','api') NOT NULL DEFAULT 'manual',
  `orderId` varchar(36) DEFAULT NULL,
  `orderItemId` varchar(36) DEFAULT NULL,
  `customerId` varchar(36) DEFAULT NULL,
  `soldAt` datetime DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `likecardOrderId` varchar(100) DEFAULT NULL,
  `likecardReferenceId` varchar(100) DEFAULT NULL,
  `productId` varchar(255) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `oauth_exchange_codes` (
  `id` varchar(36) NOT NULL,
  `createdAt` datetime(6) NOT NULL DEFAULT current_timestamp(6),
  `updatedAt` datetime(6) NOT NULL DEFAULT current_timestamp(6) ON UPDATE current_timestamp(6),
  `deletedAt` datetime(6) DEFAULT NULL,
  `code` varchar(64) NOT NULL,
  `accessToken` text NOT NULL,
  `refreshToken` text NOT NULL,
  `expiresIn` int(11) NOT NULL,
  `expiresAt` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `IDX_oauth_exchange_codes_code` (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

ALTER TABLE `order_items`
  ADD COLUMN `fulfillmentStatus` enum('not_applicable','pending','fulfilled','partial') NOT NULL DEFAULT 'not_applicable',
  ADD COLUMN `deliveredCodes` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`deliveredCodes`));

ALTER TABLE `orders`
  ADD COLUMN `idempotencyKey` varchar(100) DEFAULT NULL,
  ADD UNIQUE KEY `IDX_orders_idempotencyKey` (`idempotencyKey`);

ALTER TABLE `product_variants`
  ADD COLUMN `giftCardSupplierConfig` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`giftCardSupplierConfig`)),
  ADD COLUMN `likecardProductId` varchar(100) DEFAULT NULL;

ALTER TABLE `products`
  MODIFY COLUMN `region` enum('uae','ksa','qatar','kuwait','oman','bahrain','international','global') NOT NULL DEFAULT 'global';
